def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    pop_size = 20
    n_iter = budget // (2 * dim)
    sigma = 0.5
    T = 10000.
    cooling_rate = 0.995

    for _ in range(n_iter):
        population = rng.uniform(lb, ub, (pop_size, dim))
        objective_values = func(population)

        idx = np.argsort(objective_values)[:10]
        parents = population[idx]

        for i in range(10):
            mutant = parents[i] + sigma * rng.randn(dim)
            mutant = clip(mutant)
            trial = np.where(rng.rand(dim) < 0.5, mutant, parents[i])
            trial = clip(trial)

            if func(trial) < objective_values[idx[i]]:
                population[idx[i]] = trial
                objective_values[idx[i]] = func(trial)

        T *= cooling_rate

    return np.argmin(func(population))

def algorithm(func, dim, lb, ub, budget, rng):
    def evaluate(x):
        return func(x)

    x0 = (np.random.uniform(lb, ub) for _ in range(dim))
    best_x = np.array(list(x0))

    T = 10000
    t = 0

    while t < budget:
        x = np.array([np.clip(i, lb, ub) for i in list(np.add(best_x, rng.normal(0, 1, dim)))])
        fx = evaluate(x)

        if t > 0 and np.random.rand() < np.exp(-(fx - evaluate(best_x)) / T):
            best_x = x

        t += 1
        T *= 0.99

    return best_x

